head.script:
scwin.screenId = "jlddst05001";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.init();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05001.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst05001.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_fnDownload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnDownload_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnDownload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnDownload(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05001.btn_fnDownload_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/corpgeneral/listedissuestatusdetail.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst05001.tx_fnDownload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/listedissuestatusdetail.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst05001.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("forward", 'listedissuestatdetail_sub');
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "10");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#searchForm").attr('onsubmit', '');
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "listedissuestatdetail_down");
    await scwin.tx_fnDownload();
    $("#searchForm").attr('onsubmit', 'return false;');
    /* sdd-asis-lifecycle:end */
};
